import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"核心同步流程","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/sync.md","filePath":"zh-Hans/deep-dive/sync.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/sync.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="核心同步流程" tabindex="-1">核心同步流程 <a class="header-anchor" href="#核心同步流程" aria-label="Permalink to “核心同步流程”">​</a></h1><p>核心同步流程由 <code>packages/plugin/src/modules/Sync.ts</code> 中的 <code>Sync</code> 实现。它按同步策略给本地和远端状态分桶，把每个桶与持久的记录存储比较，创建任务计划，并针对<a href="./file-system">文件系统抽象</a>执行计划。</p><h2 id="同步触发器" tabindex="-1">同步触发器 <a class="header-anchor" href="#同步触发器" aria-label="Permalink to “同步触发器”">​</a></h2><p>调度器接收来自手动控制、<a href="./../usage/settings#实时同步">实时同步</a>、<a href="./../usage/settings#聚焦同步">聚焦同步</a>、<a href="./../usage/settings#启动同步">启动同步</a>和<a href="./../usage/settings#定时同步">定时同步</a>的请求。触发器名称是 <code>manual</code>、<code>nonInteractiveManual</code>、<code>realtime</code>、<code>focus</code>、<code>startup</code> 和 <code>interval</code>。</p><p>每个触发器名称可以携带一个已注册条目，带优先级和选项工厂。待处理请求等待插件空闲，然后冲刷成一次同步：调度器把批次的触发器名称归约到优先级最高的条目，由该条目的 <code>options()</code> 定制这次运行。没有已注册条目的批次回退到 <code>unknown</code> 触发器并使用默认选项。批次中的每个请求得到相同的结果。</p><p>内置条目由 Bootstrap 注册：<code>realtime</code>（优先级 1000）换入快速远端列表器，当<a href="./../usage/settings#实时同步快速模式">实时同步快速模式</a>启用且缓存有条目时，复用缓存的 <code>remoteContext20000</code> 状态，跳过新的远端遍历；<code>interval</code>（2000）、<code>focus</code>（2500）、<code>startup</code>（3000）和 <code>realtime</code> 在<a href="./../usage/settings#自动同步确认删除">自动同步确认删除</a>启用时请求本地删除确认；<code>nonInteractiveManual</code>（3990）以默认选项运行；<code>manual</code>（4000）在<a href="./../usage/settings#手动同步确认操作">手动同步确认操作</a>启用时请求任务确认。非交互式手动命令使用单独的触发器，以便跳过手动任务确认。</p><p>实时事件在调度请求之前先做防抖和过滤。同步执行期间发生的变更会被忽略。重命名在其旧路径或新路径任一处于范围内时调度请求；规则配置见<a href="./../usage/settings#同步策略规则">同步策略规则</a>。</p><h2 id="取消" tabindex="-1">取消 <a class="header-anchor" href="#取消" aria-label="Permalink to “取消”">​</a></h2><p>每次运行创建一个取消引用。停止控件、进度弹窗、确认对话框和插件清理都会发布 <code>syncCanceled</code>。流程在遍历、规划、确认和执行之间检查该引用。<a href="./file-system-wrappers#cancellation-wrapper">取消包装器</a>和<a href="./request-middleware#cancellation-middleware">取消请求中间件</a>在文件系统和请求层强制执行它。</p><p>取消不回滚已完成的操作。取消之后抛出的任务错误会被忽略，但执行会等待任务 promise settle 之后才报告 <code>cancelled</code>。</p><h2 id="遍历与策略匹配" tabindex="-1">遍历与策略匹配 <a class="header-anchor" href="#遍历与策略匹配" aria-label="Permalink to “遍历与策略匹配”">​</a></h2><p>基础设施初始化之后，流程发布 <code>syncInitialized</code>，附带本次运行的 <code>Infras</code> 和编译好的匹配器。</p><p>流程只编译一次配置的策略规则，然后并发开始本地和远端发现。本地遍历用匹配器调用 <code>localFs.list(&#39;/&#39;)</code>。完整远端遍历接收一个 reporter，转发进度并对每个上报路径应用匹配器。</p><p>默认远端列表器执行完整遍历。如果远端根目录不存在，它重建根目录、清除该本地 / 远端配对的记录并返回空列表。</p><p>匹配器把每个路径解析为一个策略名称加一个 <code>advance</code> 标志。对文件，策略单独决定归属。对文件夹，<code>advance</code> 控制遍历：被同步的文件夹会被遍历，其后代继承它的策略，除非后面的兜底 <code>none</code> 规则遮蔽了它；自身不被同步、但可能包含后续规则匹配内容的文件夹会作为探针被遍历。reporter 把这些结果映射为后端 <code>list()</code> 的 <code>include</code>、<code>exclude</code> 或 <code>advance</code>。规则语法与优先级记录在<a href="./../usage/settings#同步策略规则">同步策略规则</a>。</p><p>发现之后，超过配置的<a href="./../usage/settings#最大文件大小">最大文件大小</a>的条目被移除。不含任何被同步后代的探针文件夹被剪除；含有的则保留在保留策略 <code>none</code> 之下。剩余状态被组织为按策略分桶的结构：本地和远端状态用 <code>Record&lt;string, StatsMap&gt;</code>，记录用 <code>Record&lt;string, RecordStatsMap&gt;</code>。</p><h2 id="决策器" tabindex="-1">决策器 <a class="header-anchor" href="#决策器" aria-label="Permalink to “决策器”">​</a></h2><p>规划由策略驱动。<code>decideTasks</code> 遍历按策略划分的映射，为每个策略名称查找已注册的决策器，策略没有决策器时以 <code>syncStrategyNotInstalled</code> 错误失败。每个决策器只接收自己的桶：<code>localStats</code>、<code>remoteStats</code>、<code>records</code> 和一个 <code>taskFactory</code>，它的任务被串联进本次运行的任务计划。保留策略 <code>none</code> 有内置的 pholder 决策器，只创建缺失的祖先文件夹，让位于未同步祖先之下的被同步后代能在两侧传输。</p><p>内置策略由 Bootstrap 注册，并可在<a href="./../usage/settings#同步策略">同步策略</a>规则中选择：</p><p><strong>双向同步策略</strong>：</p><p>对文件，它把当前状态与记录的本地和远端 UID 比较。根据哪一侧存在、哪一侧变更，创建上传、下载、本地删除、远端删除、记录或冲突任务。两侧都存在但没有记录时，大小相等的文件只创建记录；大小不等的成为冲突。两侧都缺失的条目产生记录删除任务。</p><p>文件夹产生目录创建、删除或记录任务。本地 / 远端的文件-文件夹错配在可以判定时替换变更的一侧；无法判定的错配使规划失败。</p><p><strong>镜像本地 / 镜像远端同步策略</strong>：</p><p>这两个决策器让一侧成为权威。它们复制权威侧的文件、创建权威侧的文件夹、删除只存在于另一侧的条目，并替换文件-文件夹错配。匹配的记录避免冗余的文件传输。键和大小都匹配但没有记录的文件会获得记录；其他没有记录的文件从权威侧复制。</p><h2 id="移动检测" tabindex="-1">移动检测 <a class="header-anchor" href="#移动检测" aria-label="Permalink to “移动检测”">​</a></h2><p>除非运行禁用了它，移动检测在决策器之后运行。它把同一侧的一个删除任务与一个创建任务配对（记录的 / 当前的文件 UID 匹配），然后把这对替换为 <code>moveLocal</code> 或 <code>moveRemote</code>。</p><p>它反复寻找文件夹的删除 / 创建对。只有每个相关子项都有兼容的移动、进入同一目的地且保留基名时，文件夹对才会被转换。没有记录身份的新文件、不完整的子计划和不明确的目的地保持为普通的删除 / 创建操作。</p><h2 id="确认" tabindex="-1">确认 <a class="header-anchor" href="#确认" aria-label="Permalink to “确认”">​</a></h2><p>两个确认闸门在移动检测之后、任务执行之前运行。手动任务确认由 <code>manual</code> 触发器条目在<a href="./../usage/settings#手动同步确认操作">手动同步确认操作</a>启用时请求。添加记录和删除记录的任务不显示在列表中；取消对话框即取消本次运行。</p><p>自动本地删除确认由 <code>realtime</code>、<code>interval</code>、<code>focus</code> 和 <code>startup</code> 触发器条目在<a href="./../usage/settings#自动同步确认删除">自动同步确认删除</a>启用时请求。对话框包含 <code>removeLocal</code> 任务。选择重新上传会变成上传或远端目录创建任务。</p><p>两种确认都会在进度弹窗中挂载一个<a href="./file-tree">文件树</a>组件。</p><h2 id="冲突解决器" tabindex="-1">冲突解决器 <a class="header-anchor" href="#冲突解决器" aria-label="Permalink to “冲突解决器”">​</a></h2><p>冲突任务把 <code>key</code>、本地和远端文件状态、两个文件系统和记录存储传给所选的解决器。解决器由模块注册，按<a href="./../usage/settings#冲突解决策略">冲突解决策略</a>选择。内置策略及其面向用户的行为记录在该页。</p>`,33)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};